const assert = require('assert');
const path = require('path');
const root = process.cwd();
const { buildSchema } = require(root + '/src/utilities/buildASTSchema.ts');
const { parse } = require(root + '/src/language/parser.ts');
const { validate } = require(root + '/src/validation/validate.ts');
const { OverlappingFieldsCanBeMergedRule: head } = require(root + '/src/validation/rules/OverlappingFieldsCanBeMergedRule.ts');
const { naturalCompare } = require(root + '/src/jsutils/naturalCompare.ts');
const { execFileSync } = require('child_process');
const Module = require('module');
const filename = root + '/src/validation/rules/OverlappingFieldsCanBeMergedRule.ts';
const source = execFileSync('git', ['show', 'main:src/validation/rules/OverlappingFieldsCanBeMergedRule.ts'], {encoding:'utf8'});
const babel = require(root + '/node_modules/@babel/core');
const oldModule = new Module(filename, module);
oldModule.filename = filename;
oldModule.paths = Module._nodeModulePaths(path.dirname(filename));
oldModule._compile(babel.transformSync(source, {filename}).code, filename);
const base = oldModule.exports.OverlappingFieldsCanBeMergedRule;
describe('review checks', function () {
 this.timeout(120000);
 it('compares reordered arguments with large numeric suffixes', () => {
   const a = 'a9007199254740992', b = 'a9007199254740993';
   const schema = buildSchema(`type Query { f(${a}: Int, ${b}: Int): Int }`);
   const doc = parse(`{ f(${a}: 1, ${b}: 2) f(${b}: 2, ${a}: 1) }`);
   console.log('comparator', naturalCompare(a,b), 'base', validate(schema, doc, [base]).map(e=>e.message), 'head', validate(schema, doc, [head]).map(e=>e.message));
 });
 it('times argumentless overlapping fields', () => {
   const schema = buildSchema('type Query { f: Int }');
   for (const n of [100, 1000]) {
    const doc = parse('{ ' + 'f '.repeat(n) + '}');
    for (let round=0; round<3; round++) for (const rule of [base,head]) {
     const t = performance.now();
     assert.equal(validate(schema, doc, [rule]).length,0);
     console.log(n,round,rule===base?'base':'head',performance.now()-t);
    }
   }
 });
});
